/// <summary>
///     The <c>SalesLineBackOrderFrm_GridFilterInventSiteIdFld_Extension</c> class is the extension for <c>SalesLineBackOrder</c>
/// </summary>
[ExtensionOf(formControlStr(SalesLineBackOrder, GridFilterInventSiteId))]
final class SalesLineBackOrderFrm_GridFilterInventSiteIdFld_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean         retVal;
    InventSiteId    qValue;

    FormDataSource  locSalesTableDS;
    FormDataSource  locSalesLineDS;

    locSalesTableDS = element.SalesTable_DS;
    locSalesLineDS  = element.SalesLine_DS;

    retVal = next modified();

    qValue = element.GridFilterInventSiteId.valueStr();

    if (qValue != '')
    {
        SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, InventSiteId)).value(queryValue(qValue));
    }
    else
    {
        SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, InventSiteId)).value(SysQueryRangeUtil::valueUnlimited());
    }

    locSalesLineDS.executeQuery();

    return retVal;
}
